/* ===== VENDOR v2 - INSIDE DASHBOARD - ADMIN FUNDS, ACTIVATION DEDUCTS ===== */
const getVendorByUser=(uid)=>{try{return db.prepare("SELECT * FROM vendors WHERE user_id=?").get(uid)}catch{return null}};
const vendorRegister=(req,res)=>{try{const u=getSessionUser(req);if(!u)return res.status(401).json({success:false,message:"Login first"});const ex=getVendorByUser(u.id);if(ex)return res.json({success:true,alreadyExists:true,message:"You already applied as vendor - Status: "+ex.status,vendor:ex});const code="VND-"+Math.random().toString(36).slice(2,7).toUpperCase();db.prepare("INSERT INTO vendors (user_id,code,vendor_name,phone,status) VALUES (?,?,?,?, 'PENDING')").run(u.id,code,String(req.body?.vendor_name||req.body?.name||u.full_name||u.username),String(req.body?.phone||u.phone||""));return res.json({success:true,message:"Vendor application sent - wait for Admin to approve you",vendor:db.prepare("SELECT * FROM vendors WHERE user_id=?").get(u.id)});}catch(e){return res.status(500).json({success:false,message:e.message})}};
const vendorMe=(req,res)=>{try{const u=getSessionUser(req);if(!u)return res.status(401).json({success:false,message:"Session expired"});const v=getVendorByUser(u.id);if(!v)return res.json({success:false,isVendor:false,is_vendor:false,message:"Not a vendor yet"});const b=bals(u);return res.json({success:true,isVendor:v.status==="APPROVED",is_vendor:v.status==="APPROVED",vendor:v,vendor_status:v.status,vendor_balance:Number(v.balance||0),user:{...clean(u),balances:b},balances:b,affiliate_balance:b.affiliate_balance});}catch(e){return res.status(500).json({success:false,message:e.message})}};
const vendorPendingUsers=(req,res)=>{try{const u=getSessionUser(req);if(!u)return res.status(401).json({success:false,message:"Session expired"});const v=getVendorByUser(u.id);if(!v||v.status!=="APPROVED")return res.status(403).json({success:false,message:"Vendor not approved yet"});let rows=[];try{rows=db.prepare("SELECT * FROM users WHERE account_status NOT IN ('active','approved') OR account_status IS NULL ORDER BY id DESC LIMIT 100").all()}catch{rows=[]}return res.json({success:true,users:rows.map(x=>({...clean(x),balances:bals(x),activation_cost:PKG_COST[normPkg(x)]||9000})),total:rows.length,vendor_balance:Number(v.balance||0)});}catch(e){return res.status(500).json({success:false,message:e.message})}};
const vendorActivate=(req,res)=>{try{
const u=getSessionUser(req);if(!u)return res.status(401).json({success:false,message:"Session expired"});
const v=getVendorByUser(u.id);if(!v)return res.status(403).json({success:false,message:"Not a vendor"});
if(v.status!=="APPROVED")return res.status(403).json({success:false,message:"Vendor not approved yet - Admin must approve you first"});
const targetId=Number(req.body?.userId||req.body?.id||req.params?.id||0);if(!targetId)return res.status(400).json({success:false,message:"User ID required"});
const target=db.prepare("SELECT * FROM users WHERE id=?").get(targetId);if(!target)return res.status(404).json({success:false,message:"User not found"});
const st=String(target.account_status||target.status||"").toLowerCase();if(["active","approved"].includes(st))return res.status(400).json({success:false,message:"User already active"});
const pkg=normPkg(target);const cost=PKG_COST[pkg]||9000;const vendorBal=Number(v.balance||0);
if(vendorBal<cost)return res.status(400).json({success:false,message:`Insufficient Vendor Fund! You need ₦${cost.toLocaleString()} to activate ${pkg} user. Your balance: ₦${vendorBal.toLocaleString()}. Ask Admin to fund you.`,need:cost,balance:vendorBal,package:pkg});
db.prepare("UPDATE vendors SET balance=COALESCE(balance,0)-?, total_activated=COALESCE(total_activated,0)+1, total_deducted=COALESCE(total_deducted,0)+? WHERE id=?").run(cost,cost,v.id);
try{db.prepare("UPDATE users SET affiliate_balance=GREATEST(0,COALESCE(affiliate_balance,0)-?) WHERE id=?").run(cost,u.id)}catch{}
try{db.prepare("UPDATE users SET account_status='active' WHERE id=?").run(targetId)}catch{}
try{db.prepare("UPDATE users SET status='active' WHERE id=?").run(targetId)}catch{}
const bon=payRef(db.prepare("SELECT * FROM users WHERE id=?").get(targetId));
try{db.prepare("INSERT INTO wallet_transactions (user_id,type,amount,balance_type,reference,description,created_at) VALUES (?,?,?,?,?,?,datetime('now'))").run(u.id,"vendor_activation_deduct",-cost,"vendor",`VENDOR_ACT_${targetId}`,`Vendor activation - ₦${cost.toLocaleString()} deducted for activating ${target.username} (${pkg})`)}catch{}
try{notify(u.id,"Vendor Activation - Deducted",`₦${cost.toLocaleString()} deducted from your Vendor Balance for activating ${target.username} (${pkg}). New Vendor Balance: ₦${(vendorBal-cost).toLocaleString()}`)}catch{}
try{notify(targetId,"Account Activated ✅",`Your ${pkg} account don activate by Vendor ${u.username}. Welcome bonus don enter.`)}catch{}
return res.json({success:true,message:`${target.username} (${pkg}) activated ✅ ₦${cost.toLocaleString()} deducted from your Vendor Balance. Remaining: ₦${(vendorBal-cost).toLocaleString()}`,deducted:cost,cost,remaining_balance:vendorBal-cost,vendor_balance:vendorBal-cost,user:clean(db.prepare("SELECT * FROM users WHERE id=?").get(targetId)),referralBonus:bon});
}catch(e){return res.status(500).json({success:false,message:e.message})}};
const vendorHistory=(req,res)=>{try{const u=getSessionUser(req);if(!u)return res.status(401).json({success:false,message:"Session expired"});const v=getVendorByUser(u.id);if(!v)return res.status(403).json({success:false,message:"Not a vendor"});let tx=[];try{tx=db.prepare("SELECT * FROM wallet_transactions WHERE user_id=? AND (type LIKE '%vendor%' OR description LIKE '%Vendor%') ORDER BY id DESC LIMIT 100").all(u.id)}catch{}return res.json({success:true,vendor:v,history:tx,transactions:tx,total:tx.length});}catch(e){return res.status(500).json({success:false,message:e.message})}};
const adminVendors=(req,res)=>{try{let rows=db.prepare("SELECT v.*, u.username,u.email,u.full_name,u.package,u.account_status FROM vendors v LEFT JOIN users u ON u.id=v.user_id ORDER BY v.id DESC LIMIT 200").all();return res.json({success:true,vendors:rows,total:rows.length})}catch(e){return res.status(500).json({success:false,message:e.message})}};
const adminVendorAction=(req,res)=>{try{const id=Number(req.body?.id||req.body?.vendorId||req.params?.id||0);const act=String(req.body?.action||req.body?.status||"").toUpperCase();if(!id)return res.status(400).json({success:false,message:"Vendor ID required"});const v=db.prepare("SELECT * FROM vendors WHERE id=?").get(id);if(!v)return res.status(404).json({success:false,message:"Vendor not found"});const st=act.includes("APPROV")?"APPROVED":act.includes("REJECT")?"REJECTED":act.includes("SUSPEND")?"SUSPENDED":"PENDING";db.prepare("UPDATE vendors SET status=? WHERE id=?").run(st,id);return res.json({success:true,message:`Vendor ${st}`,vendor:db.prepare("SELECT * FROM vendors WHERE id=?").get(id)});}catch(e){return res.status(500).json({success:false,message:e.message})}};
const adminCreditVendor=(req,res)=>{try{const id=Number(req.body?.id||req.body?.vendorId||req.params?.id||0);const amt=Number(req.body?.amount||0);if(!id||!amt||amt<=0)return res.status(400).json({success:false,message:"Vendor ID + amount required"});const v=db.prepare("SELECT * FROM vendors WHERE id=?").get(id);if(!v)return res.status(404).json({success:false,message:"Vendor not found"});const user=db.prepare("SELECT * FROM users WHERE id=?").get(v.user_id);if(!user)return res.status(404).json({success:false,message:"Vendor user not found"});db.prepare("UPDATE vendors SET balance=COALESCE(balance,0)+? WHERE id=?").run(amt,id);try{db.prepare("UPDATE users SET affiliate_balance=COALESCE(affiliate_balance,0)+? WHERE id=?").run(amt,v.user_id)}catch{}try{db.prepare("INSERT INTO wallet_transactions (user_id,type,amount,balance_type,reference,description,created_at) VALUES (?,?,?,?,?,?,datetime('now'))").run(v.user_id,"vendor_funded",amt,"vendor",`VENDOR_FUND_${id}`,`Admin funded Vendor Balance +₦${amt.toLocaleString()} - you fit activate users now`)}catch{}try{notify(v.user_id,"Vendor Funded 💰",`Admin don fund your Vendor Balance with ₦${amt.toLocaleString()}. You fit activate users now. SILVER ₦9,000 / GOLD ₦15,000 / SUPER ₦21,000 go deduct per activation.`)}catch{}return res.json({success:true,message:`Vendor ${user.username} funded ₦${amt.toLocaleString()}. New Vendor Balance: ₦${(Number(v.balance||0)+amt).toLocaleString()}`,vendor:db.prepare("SELECT * FROM vendors WHERE id=?").get(id)});}catch(e){return res.status(500).json({success:false,message:e.message})}};
